args.query:
\d api.application
\d api.app_user
\d reg.counterparty
select rolname from pg_roles where rolname !~ '^pg_';
select grantee,table_name,privilege_type from information_schema.role_table_grants where table_schema in ('api','reg') order by 2,1;
select * from api.app_user;
select tablename,policyname,roles,cmd,qual,with_check from pg_policies;
select tgname,tgrelid::regclass from pg_trigger where not tgisinternal;
select c.relname,c.relrowsecurity,pg_get_userbyid(c.relowner) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('api','reg') and relkind in('r','v','f');

select * from api.status;
select grantee,table_name,column_name,privilege_type from information_schema.column_privileges where table_schema='api' and grantee in('applicant','expert','lawyer','anon') order by 2,1,3;
select n.nspname,p.proname,prosecdef,pg_get_functiondef(p.oid) from pg_proc p join pg_namespace n on n.oid=pronamespace where nspname in('priv','api','reg');
select nspname,nspacl from pg_namespace where nspname in('api','priv','reg');
select application.number,status_id,amount,company_inn from api.application order by 1;
select * from reg.counterparty;

create table api.contract(
 id int generated always as identity primary key,
 number text not null unique,
 application_id int not null references api.application(id),
 amount numeric not null check (amount>0),
 signed_on date not null default current_date,
 status text not null default 'Проект' check (status in ('Проект','Подписан')));
create index on api.contract(application_id);
create function priv.check_contract() returns trigger language plpgsql security definer set search_path to 'api' as $$
begin
 if not exists (select 1 from api.application a join api.status s on s.id=a.status_id where a.id=new.application_id and s.name='Одобрена') then
  raise exception 'договор можно заключить только по одобренной заявке' using errcode='check_violation'; end if;
 return new; end $$;
create trigger check_contract before insert or update on api.contract for each row execute function priv.check_contract();
create function priv.contract_company(int) returns text language sql stable security definer set search_path to 'api' as $$ select company_inn from api.application where id=$1 $$;
alter table api.contract enable row level security;
create policy admin_all on api.contract for all to fund_admin using(true) with check(true);
create policy lawyer_all on api.contract for all to lawyer using(true) with check(true);
create policy applicant_read on api.contract for select to applicant using (priv.contract_company(application_id)=priv.my_company());
grant select,insert,update,delete on api.contract to fund_admin;
grant select,insert,update on api.contract to lawyer;
grant select on api.contract to applicant;
grant usage on schema api,priv to lawyer;
grant execute on function priv.contract_company(int), priv.my_company(), priv.login(), priv.status_ord(int), priv.status_id(text) to public;
grant select on api.application, api.status to lawyer;
create policy lawyer_read on api.application for select to lawyer using(true);
create view api.company as select inn, legal_name, funding_limit from reg.counterparty;
grant select on api.company to lawyer, fund_admin;
create view api.limit_balance as
select c.legal_name as company, c.funding_limit, a.approved,
 coalesce(k.contracted,0) as contracted, c.funding_limit-coalesce(k.contracted,0) as remaining
from reg.counterparty c
join (select a.company_inn, sum(a.amount) approved from api.application a join api.status s on s.id=a.status_id and s.name='Одобрена' group by 1) a on a.company_inn=c.inn
left join (select p.company_inn, sum(k.amount) contracted from api.contract k join api.application p on p.id=k.application_id group by 1) k on k.company_inn=c.inn;
grant select on api.limit_balance to lawyer, fund_admin;
update api.app_user set role='lawyer' where login='lawyer1';
select pg_has_role('authenticator','lawyer','member');
notify pgrst,'reload schema';
